-- lyric previews from LRCLIB (scripts/fetch-previews.mjs). Safe to re-run; never overwrites an existing preview.
alter table public.songs add column if not exists preview text check (char_length(preview) <= 200);

update public.songs set preview = v.preview from (values
('mua dong tinh yeu|huong tram', 'Ngày dài hơn để anh biết nhớ Một cơn mưa vội vàng đến nhanh Từng khao khát tình yêu từ sâu tận nơi tim anh Mùa đông sắp đến mang theo Từng cơn gió, đôi tay ai đang cô đơn Cho anh đ'),
('nhan gui thanh xuan|huong tram', 'Nhớ mãi phút giây ban đầu ấy Ta đã lớn bên nhau từng ngày Thời gian cứ dần trôi ai có hay Giờ mình cùng ngồi xuống đây kể lại Một thời học sinh đấy tuy chẳng dài Nhưng trong ta làm'),
('anh the gioi va em|huong tram', 'Sẽ có người yêu em hơn anh Anh đã nói vậy ngày chia tay đứng chết lặng trông theo bóng dáng cứ xa dần Đã lâu rồi trong em vẫn thế vẫn chưa phai chuyện cũ và anh Giống như chỉ hôm q'),
('lang nghe mua xuan ve|huong tram', 'Giọt mưa nào rơi thật êm trên phố phường Mùi hương nào thơm thật thơm trong gió thoảng Và anh đợi em, đợi em như đã hẹn Nghe trong mưa đêm mùa xuân lặng lẽ sang Phải chăng mầm non '),
('tinh dep den may cung tan|huong ly', 'Sau bao nhiêu mối tình đổ vỡ Mình còn tin ai Sau bao nhiêu tổn thương bủa vây Vẫn yêu em rất miệt mài Qua bao nhiêu khoảng khắc thời gian Tưởng chừng hạnh phúc nhất Phút chốc tan v'),
('huong xua|huong ly', 'Không hiểu vì sao ta có buổi chiều nay Gặp lại nhau rồi bỗng dưng em khóc Giọt nước mắt em làm sao ngăn được Anh bây giờ như xa một tầm tay Anh bây giờ như xa một tầm tay Biết nói '),
('co tat ca nhung thieu anh|huong ly', 'Em đang trong từng ngày Nhìn anh đổi thay Em chưa bao giờ nghĩ là nhanh đến vậy Có những nỗi buồn Từ đâu chẳng một ai muốn Nhưng tại sao? Một người nơi nao Tự nhiên cướp lấy em đi '),
('vui lam nha|huong ly', 'Mình ở bên nhau cuộc đời vui lắm nha Cột dây tơ duyên hai đứa thương tới già Anh nói mai này em sẽ no ấm cùng anh Hỡi khoan hò khoan em nguyện yêu thật lòng Mình ở bên nhau đời lại'),
('the gioi trong em|huong ly', 'Chẳng biết lâu nay Tại sao em cứ mãi vấn vương Lần đầu gặp anh Đã khiến cho trái tim này nhớ thương Ngày thì đăng tus thả thính Xong rồi về đêm lại ngồi cười Vì người đầu tiên thả '),
('chua bao gio em quen|huong ly', 'Có những lúc buồn cũng chẳng biết nói với ai Từng dòng cảm xúc cứ mãi quấn quanh trong đầu Có những kỉ niệm bây giờ chỉ là quá khứ Có những yêu thương bây giờ chỉ còn trong mơ Nhữn'),
('em cung can mot bo vai|huong ly', 'Đừng yêu ai anh nhé, đừng bỏ em một mình Đừng nói lời ong bướm, mật ngọt đầu môi Đừng yêu ai anh nhé, hãy dìu em chung đường Hãy nói dùm em hai tiếng yêu đương Đừng yêu ai anh nhé,'),
('anh thoi nhan nhuong|huong ly', 'Chẳng buồn tương tư làm chi nên em chọn cách ngoảnh đầu bước đi Dành cả thanh xuân gửi trao mà anh nỡ ngó lơ là sao Dừng lại em cũng đau lắm nhưng em không muốn mình phải vấn vương'),
('em muon ta la gi|huong ly', 'Phải xa rời nhau chẳng ai muốn vậy Để con tim của hai chúng ta đau đớn như thế này Giờ ai sai và ai đúng đâu có quan trọng Khi anh muốn xa rời nói thêm cũng bằng không Anh muốn kết'),
('sau nay neu co thuong em|huong ly', 'Em, một cô gái đã trải qua nhiều lần đổ vỡ Một quá khứ không may mắn trong chuyện tình yêu Em đã mất bao lâu mới có thể quen dần, đã mất bao lâu để vết thương lành Rất khó để em bắ'),
('buon lam em oi|huong ly', 'Em ước gì mình gặp được anh sớm hơn Và người nắm tay anh không phải là cô ta Để mỗi khi cô đơn lại về không quá nặng nề Giằng xé tâm tư của một người đến sau Phố xá đông người nhưn'),
('khong sao ma em day roi|huong ly', 'Hình như anh đang say Hình như anh không vui Kể cho em nghe đi Vì sao anh buồn thế Nếu muốn khóc hãy cứ khóc trên vai em này Đừng cứ mãi ôm lấy nỗi đau như vậy Hình như mưa đang rơ'),
('tung yeu|huong ly', 'Có kí ức nào đẹp hơn ngày đôi ta bắt đầu Có đớn đau nào nặng hơn ngày mình xa nhau Có đôi mắt nào buồn hơn bờ mi em tuôn sầu Có đắng cay nào bằng em vội vàng qua mau Người đàn ông '),
('em di giua bien vang|huong ly', 'Em đi giữa biển vàng Nghe mênh mang trên đồng lúa hát Hương lúa chín thoang thoảng bay Làm lung lay hàng cột điện Làm xáo động cả rặng cây Em đi giữa biển vàng Nghe mênh mang trên '),
('yeu ai de khong phai khoc|huong ly', 'Khi tình yêu nhạt phai Chẳng ai nhận lỗi do mình đã sai Chỉ đơn giản lặng im và đi Chỉ cần không thấy nhau Buông để không phải đau Còn nhớ, còn thương em bỏ phía sau Lặng lẽ bước g'),
('tinh yeu tren dong song quan ho|huong ly', 'Tình yêu có từ nơi đâu Em êm một khúc sông Cầu Sao trời lọt qua mắt lưới Rơi đầy xuống dòng sông sâu Tình đã trao nhau êm đềm Em là cô Tấm thảo hiền Mà mắt vẫn nhìn bối rối Gặp nha'),
('la ai tu bo, la ai vo tinh|huong ly', 'Ngày ấy vì người lỡ trao hoa dại Ta nghĩ là mùa xuân Ngày ấy vì lời vấn vương nhất thời Cõi lòng em nát tan một nơi Lời ai nói suốt kiếp mãi sẽ không rời Lời ai nói trên đôi môi ki'),
('la ai tu bo la ai vo tinh|huong ly', 'Ngày ấy vì người lỡ trao hoa dại Ta nghĩ là mùa xuân Ngày ấy vì lời vấn vương nhất thời Cõi lòng em nát tan một nơi Lời ai nói suốt kiếp mãi sẽ không rời Lời ai nói trên đôi môi ki'),
('mot buoc yeu van dam dau|huong ly', 'Hôm nay Dành hết lầm lỗi để chia tay Tình ta từ nay vỡ đôi Một dòng nước mắt lăn chậm qua môi heh ah, heh ah Một thế giới hư ảo nhưng thật ấm áp Anh xuất hiện khiến những băng giá '),
('nhin may ve nguoi|huong ly', 'Từng lời ca í a, viết đôi câu tình vương Lòng này ai thấu đâu, mấy trùng xa biết ai còn thương Trông mây họa lên tình nhân, đưa tay vội ôm lấy trời Để giờ người không với tới, lòng'),
('nho ha noi|huong ly', 'Dù có đi bốn phương trời Lòng vẫn nhớ về Hà Nội Hà Nội của ta, Thủ đô yêu dấu Một thời đạn bom Một thời hòa bình Nhớ phố thâm nghiêm rợp bóng cây Tiếng ve ru những trưa hè Và nhớ n'),
('bai ca nguoi giao vien nhan dan|huong ly', 'Trên những nẻo đường của Tổ quốc xanh tươi Có những loài hoa thơm đậm đà sắc hương Có những bài ca nghe rạo rực lòng người Bài ca ấy loài hoa ấy đẹp như em Người giáo viên nhân dân'),
('mua thu ngay khai truong|huong ly', 'Tiếng trống trường rộn rã làm tan cái nắng hè Dịu đi những tiếng ve còn vương trên vòm cây xanh lá Mùa thu sang đẹp quá Xao xuyến bao tâm hồn vui tiếng trống tựu trường Trang giáo '),
('neu co mot ngay|huong ly', 'Nếu có một ngày góc phố nhỏ vắng tiếng cười Nếu có một ngày đôi tay này bỗng buông lơi Mây treo đầy trời mà sao tìm chẳng thấy người Có những niềm riêng chẳng thể biết trước người '),
('ai chuyen cu ban khong|huong ly', 'Ai chuyện cũ bán hôn? Trời ơi bên kia Hình như có gì bốc cháy Khói bay tứ tung Làm cho cả xóm lùng bùngMột bên xôn xao Một bên lại nhốn nháo Khắp cả khu phố Mặt ai cũng nóng bừng b'),
('phia sau canh cua|huong ly', 'Có khi nào, giữa những ồn ào Có khi nào, chợt nhận ra ta hư hao? Có khi nào, ngoảnh lại phía sau như ai đang thét gào? Có khi nào, là ta... Một chút ngỡ ngàng, một thoáng mơ hồ Là '),
('do ta khong do nang|huong ly', 'Phật ở trên kia cao quá Mãi mãi không độ tới nàng Vạn dặm tương tư vì ai Tiếng mõ vang lên phũ phàng Chùa này không thấy bóng nàng Bồ đề chẳng muốn nở hoa Dòng kinh còn lưu vạn chữ'),
('dong|truc nhan', 'Ngày dài mưa phùn nắng gió tiêu điều Quanh đây đâu đâu mây lặng bay Ngoài trời khung cửa trắng xoá lối đi Xa xa một nhánh cây tàn khô Đôi tình nhân kia hãy hôn nhau đi Tìm trong là'),
('cham gan them thuong|truc nhan', 'Hoo, oo-oo-oo-ooh Hoo, oo-oo-oo-ooh Hoo, oo-oo-oo-ooh Ooh, oo-oo-oo-oo-oo-ooh Hoo, oo-oo-oo-ooh Hoo, oo-oo-oo-ooh Hoo, oo-ooh, oo-ooh, oo-ooh Chạm tay, chạm tay, vuốt làn tóc mai T'),
('that bat ngo|truc nhan', 'Hey, hey Trên báo những thông tin chen nhau đi một hàng Người đàn bà hở hang, xong đến chuyện người thì nở nang Xong đến chuyện mặt hàng thời trang Lôi cuốn người người đọc vào ban'),
('neu mot mai toi bay len troi|truc nhan', 'Nhắm mắt thấy tôi quay về Về với bữa cơm nhà, mà bao lâu tôi bỏ qua Nhắm mắt thấy ba mẹ ngồi Bên đứa em thơ dại, nhìn lại năm tháng qua Tôi học cách yêu thương người khác tôi Và ba'),
('sang mat chua|truc nhan', 'Ba mẹ anh từng nói yêu ai phải yêu xứng đôi vừa lứa Hình như không ai dạy em nên em còn non em chưa học qua Cách chọn Đúng người Chàng trai đi cùng đang ăn cây kem thật lòng không '),
('co khong giu mat dung tim|truc nhan', 'Bất ngờ em nói chia tay Dù lúc tôi đang yêu em đắm say (yêu em đắm say) Và thế rồi em mất tăm hơi Mặc xác tôi nơi này lòng chơi vơi Hết hồn nay em nhắn cho tôi Rồi nói em đang mong'),
('ve duong cong|truc nhan', '(Oh no) Bao lâu rồi bộn bề nhiều suy nghĩ? Loay hoay như con quay, thân mình lại chẳng để ý (Oh no) Sao trông khuôn mặt mình thật nhàu nhĩ? (haizz) Không quan tâm skincare, tóc tai'),
('lon roi con khoc nhe|truc nhan', 'Ngày thơ bé có cánh đồng, trưa nắng bên bờ sông Thời tôi chưa biết vâng lời, chỉ biết chơi và cười Lời mẹ nói không nghe cho rằng luôn khắt khe Mẹ nói, "Con trai đừng khóc nhè!" Ng'),
('cam on da chung duong|truc nhan', 'Tôi ngây ngô đi ra gặp bao nhiêu người Rồi sinh ra những cảm xúc gọi là chờ mong Tôi đi xa vời vợi lòng chẳng trông đợi Rồi thấy có những phương hướng Gọi là phải lòng Và ngay đây,'),
('nguoi ta co thuong minh dau|truc nhan', 'Từ trong tâm trí Trót đã lỡ yêu thương một người Mơ môi khẽ chạm môi Mơ tay khẽ chạm tay siết chặt tay mà người đâu có hay Có lúc tôi mong tim ta cùng chung nhịp Lắm lúc tôi mong c'),
('vi anh qua dep trai|truc nhan', 'Thấy bóng dáng nàng, nàng chỉ nhấc cái dáng lông mày Tự nhiên tâm anh đang thanh tịnh, bị lung lay Vui nên hơi vội, vừa kết nối đã kết em rồi Được hay không mà như thế nào là tùy e'),
('may khi ma suong the nay|truc nhan', 'Alo homie, tôi có tin vui Sắp xếp đi chiều nay tôi sang Không lo âu chi hết ông ơi Ta sẽ chơi đến khi đêm tàn Ê honey, anh có tin vui Anh mua thêm mấy bộ đồ em mang Không lo âu chi'),
('tinh yeu mau nang|truc nhan', 'Ai mặc noọng lái lai (à há, à há) Ai mặc noọng lái lai Gọi tên của anh là nắng, để em được làm mây trắng Bên anh quấn quýt mãi chẳng rời Và khi gọi anh là mưa, chẳng thể gần lại đư'),
('chuyen tinh tu cu tu tu tinh|truc nhan', 'Kiếm đâu người mai mối, chẳng ai đem lòng yêu tôi Kiếm đâu người ăn tối với tôi xong nằm bên tôi Vì đã lâu giường hai gối thế nhưng chỉ mỗi tôi nằm Một mình Thấy hông, tình lúc có '),
('mashup toi nguoi viet nam|truc nhan', 'Một buổi chiều êm đềm quá, lòng bỗng nhớ về một nơi xa Hà Nội bình yên quá, nơi có những bản tình ca Một Sài Gòn đôi lúc có nắng, có mưa bất chợt Ôi sao thấy nhớ Việt Nam quá Giờ n'),
('giac mo tinh yeu|truc nhan', 'Có giấc mơ nào êm đềm Khẽ lướt qua làn môi mềm Lấp lánh như ngàn tia nắng Sưởi ấm cõi lòng em Vẫn biết yêu và mong chờ Vẫn biết yêu người xa vời Muốn khúc ca còn êm ái Cùng giấc mơ'),
('buon thi cu khoc di|truc nhan', 'Em có buồn Nếu anh để lại cây viết dòng thư cuối sau bức màn uhm Nghe tiếng đàn Cất lên trong không gian thật yên lặng khiến anh ngỡ ngàng Chợt dòng chữ ấy đã phai nhanh vì mắt ướt'),
('goc da hinh|vu cat tuong', 'Con đường quen, mỗi sáng là những lần kẹt xe hối hả Hai hàng cây, mỗi sáng lặng ngắm dòng người trôi dưới chân mình. Cuộc sống trở nên thật vô vị Khi mọi thứ chỉ có một góc nhìn Kh'),
('mo|vu cat tuong', 'Khi mà em Rời xa vòng tay của riêng anh Chạy theo cơn mơ Chạy theo hạnh phúc ở nơi nào Chỉ mỗi anh nơi này Nâng niu những thơ ngây Và khi anh lặng lẽ chôn giấu Bao buồn vui gói tro'),
('co nguoi|vu cat tuong', 'Chiều nay có người Hẹn anh với nụ cười tươi Chiều nay có người Dạy anh cách làm mặt vui Dường như anh cũng đã quen rồi Ngày và đêm chỉ công việc thôi Người chợt đến như ánh mặt trờ'),
('ngay nay, nguoi con gai nay|vu cat tuong', 'Lặng nhìn em thật lâu, lòng muốn nói một lời Mà dũng khí trong anh hôm nay sao xa vời vợi Chờ vài giây nữa thôi, lòng cũng thấy bồi hồi Vì ngày hạnh phúc nhất đời mình là ngày hôm '),
('hu vo|vu cat tuong', 'Đêm cô tịch, làm bạn với bóng mình Trong vô định, từ bao lâu đánh mất chính mình Ooh, cơn mê dài khởi nguồn cho tất cả tháng ngày Trong không gian cô đọng, chỉ còn ta níu lấy ảo vọ'),
('vai phut truoc|vu cat tuong', 'Vài phút trước còn nói cười Hôn thật sâu và ôm thật lâu Vài phút trước người nói với anh rằng: "Anh mãi là của em" Vài phút trước giờ tan tầm Đứng chờ em nắng cũng cười anh Vài phú'),
('em oi|vu cat tuong', 'Em ơi mình đã yêu nhau được mấy tháng rồi Em ơi mình đã qua bao nhiêu sóng gió trên đời Có mấy đêm anh thức khuya Đọc những lá thư em trao đến anh Em ơi mình đã xa nhau hơn cả tuần'),
('nguoi binh thuong|vu cat tuong', 'Anh đã qua ba lần của mười năm Anh có một thời tuổi trẻ đẹp lắm Cố gắng không để ngã gục Đổi lấy thứ anh cho là hạnh phúc Cảm ơn đời dạy anh một điều thôi Bình yên đâu phải là nơi '),
('vet mua|vu cat tuong', 'Cơn mưa đã xoá hết những ngày yêu qua Chỉ còn mình anh ngu ngơ mong cho cơn mưa Tan trong yêu thương không vội vã Mưa ngoan giấu hết những phút thẫn thờ này Thương em đi giữa đêm l'),
('mot trieu nam anh sang|vu cat tuong', 'Một triệu năm ánh sáng để đi bên em từ kiếp trước đến ngân hà Một phần nghìn giây trôi qua chợt va vào nhau trong vũ trụ bao la Một lần Trời đã lỡ để anh ngủ quên trong hành tinh c'),
('nguoi nhu anh xung dang co don|vu cat tuong', 'Ánh sáng tắt đi, chẳng để lại thứ gì Cuối cùng, mọi cố gắng chỉ là vứt đi Tìm trong ký ức vẫn còn bờ vai, môi son Từng ở bên anh, từng nắm tay anh Trí nhớ khắc sâu ngày đôi ta mất '),
('hen yeu|vu cat tuong', 'Ngày mới lên Gọi nắng lên Kề bên nhau ta nhẹ ôm những Giấc mơ vẫn còn nguyên vẹn từng giây nồng nàn Một chút thôi Một sớm mai Đời thật vui khi ta gặp nhau giữa Chốn đông người hững'),
